function handleStepRun(event) {
    event.preventDefault();

    const button = event.target.closest('.run-button');
    if (!button) return;

    const stepKey = button.dataset.step;
    if (!isValidStepKey(stepKey)) {
        console.error(`Invalid step key: ${stepKey}`);
        showErrorToast('Étape invalide');
        return;
    }

    // Vérification état
    if (isStepRunning(stepKey)) {
        showInfoToast('Étape déjà en cours');
        return;
    }

    // Action
    executeStep(stepKey);
}

function handleStepCancel(event) {
    event.preventDefault();

    const button = event.target.closest('.cancel-button');
    if (!button) return;

    const stepKey = button.dataset.step;
    if (!isValidStepKey(stepKey)) {
        console.error(`Invalid step key: ${stepKey}`);
        return;
    }

    // Action
    cancelStep(stepKey);
}
```

