## 🎯 Pattern Utilisation

**Intégration avec DOMBatcher :**
```javascript
import { domElements } from './domElements.js';
import { domBatcher } from './utils/DOMBatcher.js';

function updateStepStatus(stepKey, status) {
    const stepElement = domElements.getStepElement(stepKey);
    if (!stepElement) {
        console.error(`Cannot update status for unknown step: ${stepKey}`);
        return;
    }

    domBatcher.scheduleUpdate(() => {
        stepElement.setAttribute('data-status', status);
        stepElement.className = `step status-${status}`;
    });
}

function showStepProgress(stepKey, current, total) {
    const progressBar = domElements.getStepProgressBar(stepKey);
    if (!progressBar) {
        console.warn(`No progress bar for step: ${stepKey}`);
        return;
    }

    domBatcher.scheduleUpdate(() => {
        const percentage = total > 0 ? (current / total) * 100 : 0;
