function updateStepProgress(stepKey, current, total) {
    // Validation
    if (!isValidStepKey(stepKey)) {
        console.error(`Invalid step key for progress update: ${stepKey}`);
        return;
    }

    if (typeof current !== 'number' || typeof total !== 'number') {
        console.error(`Invalid progress values for ${stepKey}: current=${current}, total=${total}`);
        return;
    }

    // Calculs
const percentage = total > 0 ? Math.round((current / total) * 100) : 0;
    const progressText = total > 0 ? `${current}/${total}` : 'Indéterminé';

    domBatcher.scheduleUpdate(() => {
        const progressBar = domElements.getStepProgressBar(stepKey);
        if (!progressBar) {
            console.warn(`Progress bar not found for ${stepKey}`);
            return;
        }

        // Mise à jour largeur
        progressBar.style.width = `${percentage}%`;

        // Mise à jour attributs accessibilité
        progressBar.setAttribute('aria-valuenow', current);
        progressBar.setAttribute('aria-valuemax', total);
        progressBar.setAttribute('aria-valuetext', progressText);

        // Mise à jour texte visible
const progressTextElement = progressBar.querySelector('.progress-text');
        if (progressTextElement) {
            progressTextElement.textContent = `${percentage}%`;
        }

        // Mise à jour classes pour styling
        progressBar.className = `progress-fill ${getProgressClass(percentage)}`;
    });
}

function getProgressClass(percentage) {
    if (percentage === 0) return 'progress-empty';
    if (percentage < 25) return 'progress-low';
    if (percentage < 75) return 'progress-medium';
    if (percentage < 100) return 'progress-high';
    return 'progress-complete';
}
```

