function loadAudioData(aeJson) {
  if (!aeJson.metadata.audio_sync) {
    $.writeln('[AUDIO] Pas de données audio synchronisées');
    return null;
  }

  return {
    byFrame: aeJson.audioByFrame || {},
    analytics: aeJson.audioAnalytics || {}
  };
}

var audioData = loadAudioData(aeJson);
