**Synchronisation temporelle :**
```javascript
function getAudioAtFrame(frameNumber, audioData) {
  var frameKey = frameNumber.toString();

  if (audioData.byFrame[frameKey]) {
    return audioData.byFrame[frameKey];
  }

  // Recherche dans les frames adjacents (±2 frames)
  for (var offset = -2; offset <= 2; offset++) {
    var searchFrame = (frameNumber + offset).toString();
    if (audioData.byFrame[searchFrame]) {
      return audioData.byFrame[searchFrame];
    }
  }

  return null; // Pas d'audio à cette frame
}
```

