function createAudioSubtitles(comp, audioData) {
  var textLayer = comp.layers.addText("Sous-titres");
  var textProp = textLayer.property("Source Text");

  // Expression pour texte dynamique
  var expression = "";
  expression += "var frame = Math.round(time * " + fps + ");\n";
  expression += "var audioInfo = getAudioAtFrame(frame);\n";
  expression += "if (audioInfo) audioInfo.text else ''";

  textProp.expression = expression;

  // Style du texte
  var textDoc = textProp.value;
  textDoc.fontSize = 48;
  textDoc.fillColor = [1, 1, 1];
  textDoc.strokeColor = [0, 0, 0];
  textDoc.strokeWidth = 2;
  textProp.setValue(textDoc);

  return textLayer;
}
```

