```javascript
function createSpeakerMarkers(comp, audioData) {
  var markerProp = comp.markerProperty;

  if (!markerProp) return;

  // Parcours de tous les segments audio
  for (var frameKey in audioData.byFrame) {
    var audioSegment = audioData.byFrame[frameKey];
    var frameNumber = parseInt(frameKey);
    var timeSeconds = frameNumber / fps;

    // Création du marqueur
    var marker = new MarkerValue(
      audioSegment.speaker + ": " + audioSegment.text
    );

    markerProp.setValueAtTime(timeSeconds, marker);
  }
}
