La gestion des calques et masques faciaux dans ExtendScript utilise les données de tracking pour créer des compositions AE avec masques animés :

## Création de Calques Visage

**À partir des données tracking :**
```javascript
function createFaceLayers(comp, aeJson) {
  var faceLayers = [];

  // Grouper par ID de visage
  var faceIds = {};
  for (var frameKey in aeJson.dataByFrame) {
    var frameData = aeJson.dataByFrame[frameKey];
    for (var i = 0; i < frameData.length; i++) {
      var face = frameData[i];
      if (!faceIds[face.id]) {
        faceIds[face.id] = true;

        // Créer calque pour ce visage
        var faceLayer = createFaceLayer(comp, face, aeJson.metadata);
        faceLayers.push(faceLayer);
      }
    }
  }

  return faceLayers;
}

function createFaceLayer(comp, faceData, metadata) {
  // Calque vidéo source
  var videoLayer = comp.layers.add(app.project.importFile(
    new ImportOptions(File(metadata.video_name + '.mp4'))
  ));

  // Renommage
  videoLayer.name = 'Face_' + faceData.id;

  // Position initiale
  videoLayer.position.setValue([faceData.center_x, faceData.center_y]);

  return videoLayer;
}
```

## Masques Faciaux Animés

**Création de masques à partir des landmarks :**
```javascript
function createFacialMask(layer, faceId, aeJson) {
  var maskGroup = layer.Masks;
  var mask = maskGroup.addProperty("ADBE Mask Atom");

  mask.name = 'Face_Mask_' + faceId;

  // Collecter tous les points de contour
  var maskPoints = [];
  var totalFrames = aeJson.metadata.total_frames;

  for (var frame = 1; frame <= totalFrames; frame++) {
    var frameData = aeJson.dataByFrame[frame.toString()];
    if (frameData) {
      for (var i = 0; i < frameData.length; i++) {
        if (frameData[i].id === faceId) {
          var face = frameData[i];

          // Extraire points de contour facial (landmarks 0-16)
          var contourPoints = extractFacialContour(face.landmarks);
          maskPoints.push({
            frame: frame,
            points: contourPoints
          });
          break;
        }
      }
    }
  }

  // Créer keyframes pour le masque
  createMaskKeyframes(mask, maskPoints, aeJson.metadata.fps);

  return mask;
}

function extractFacialContour(landmarks) {
  // Points 0-16 = contour facial
  var contour = [];
  for (var i = 0; i <= 16; i++) {
    contour.push([landmarks[i].x, landmarks[i].y]);
  }
  return contour;
}
```

## Animation des Keyframes

**Application des positions et échelles :**
```javascript
function animateFaceLayer(layer, faceId, aeJson) {
  var positionProp = layer.position;
  var scaleProp = layer.scale;
  var opacityProp = layer.opacity;

  var fps = aeJson.metadata.fps;
  var totalFrames = aeJson.metadata.total_frames;

  for (var frame = 1; frame <= totalFrames; frame++) {
    var frameData = aeJson.dataByFrame[frame.toString()];
    var time = frame / fps;

    if (frameData) {
      for (var i = 0; i < frameData.length; i++) {
        if (frameData[i].id === faceId) {
          var face = frameData[i];

          // Position du centre
          positionProp.setValueAtTime(time, [face.center_x, face.center_y]);

          // Échelle basée sur la taille
          var scaleValue = (face.width / 100) * 100; // Normalisation
          scaleProp.setValueAtTime(time, [scaleValue, scaleValue]);

          // Opacité basée sur confidence
          var opacityValue = face.confidence * 100;
          opacityProp.setValueAtTime(time, opacityValue);

          break;
        }
      }
    }
  }
}
```

## Gestion des Expressions Faciales

**Utilisation des blendshapes ARKit :**
```javascript
function applyBlendshapeAnimations(layer, faceId, aeJson, blendshapeName) {
  var sliderEffect = layer.Effects.addProperty("ADBE Slider Control");
  sliderEffect.name = blendshapeName + '_Control';

  var sliderProp = sliderEffect.property("Slider");

  var fps = aeJson.metadata.fps;
  var totalFrames = aeJson.metadata.total_frames;

  for (var frame = 1; frame <= totalFrames; frame++) {
    var frameData = aeJson.dataByFrame[frame.toString()];
    var time = frame / fps;

    if (frameData) {
      for (var i = 0; i < frameData.length; i++) {
        if (frameData[i].id === faceId) {
          var blendshapes = frameData[i].blendshapes;
          if (blendshapes && blendshapes[blendshapeName] !== undefined) {
            var value = blendshapes[blendshapeName] * 100; // 0-100
            sliderProp.setValueAtTime(time, value);
          }
          break;
        }
      }
    }
  }
}
```

## Organisation Hiérarchique

**Structure de calques propre :**
```javascript
function organizeFaceLayers(comp, faceLayers) {
  // Créer dossier pour les visages
  var facesFolder = comp.layers.addNull();
  facesFolder.name = 'FACES';
  facesFolder.enabled = false; // Guide layer

  // Créer sous-dossiers par visage
  for (var i = 0; i < faceLayers.length; i++) {
    var faceLayer = faceLayers[i];
    var faceId = extractFaceId(faceLayer.name);

    var faceFolder = comp.layers.addNull();
    faceFolder.name = 'Face_' + faceId + '_Group';
    faceFolder.parent = facesFolder;

    // Attacher le calque au groupe
    faceLayer.parent = faceFolder;

    // Créer null pour les contrôles
    var controlNull = comp.layers.addNull();
    controlNull.name = 'Face_' + faceId + '_Controls';
    controlNull.parent = faceFolder;
  }
}
```

## Optimisations Performance

**Gestion de la mémoire pour gros projets :**
```javascript
function optimizeLayerPerformance(layer) {
  // Désactiver rendu quand hors écran
  if (layer.hasOwnProperty('collapseTransformation')) {
    layer.collapseTransformation = true;
  }

  // Qualité adaptative
  layer.quality = LayerQuality.BEST;

  // Désactiver motion blur si pas nécessaire
  layer.motionBlur = false;

  // Sampling adaptatif
  if (layer.hasOwnProperty('samplingQuality')) {
    layer.samplingQuality = SamplingQuality.BILINEAR;
  }
}
