## Animation des Positions

**Keyframes pour tous les landmarks :**
```javascript
function animateLandmarks(nullLayers, faceId, aeJson) {
  var fps = aeJson.metadata.fps;
  var totalFrames = aeJson.metadata.total_frames;

  // Pour chaque null layer
  for (var i = 0; i < nullLayers.length; i++) {
    var nullLayer = nullLayers[i].layer;
    var landmarkIndex = nullLayers[i].landmarkIndex;
    var positionProp = nullLayer.position;

    // Collecter toutes les positions pour ce landmark
    var keyframes = [];

    for (var frame = 1; frame <= totalFrames; frame++) {
      var frameData = aeJson.dataByFrame[frame.toString()];

      if (frameData) {
        for (var j = 0; j < frameData.length; j++) {
          if (frameData[j].id === faceId) {
            var face = frameData[j];

            if (face.landmarks && face.landmarks[landmarkIndex]) {
              var landmark = face.landmarks[landmarkIndex];
              var time = frame / fps;

              keyframes.push({
                time: time,
                position: [landmark.x, landmark.y]
              });
            }
            break;
          }
        }
      }
    }

    // Appliquer les keyframes
    applyLandmarkKeyframes(positionProp, keyframes);
  }
}

function applyLandmarkKeyframes(positionProp, keyframes) {
  for (var i = 0; i < keyframes.length; i++) {
    var kf = keyframes[i];
    positionProp.setValueAtTime(kf.time, kf.position);
  }
}
