## Conversion Frame ↔ Time

**Utilitaires ExtendScript :**
```javascript
function frameToTime(frameNumber, fps) {
  return frameNumber / fps;
}

function timeToFrame(timeSeconds, fps) {
  return Math.round(timeSeconds * fps);
}

function getAudioAtTime(timeSeconds, audioData) {
  var fps = 25; // Depuis metadata
  var targetFrame = timeToFrame(timeSeconds, fps);

  // Recherche dans audioByFrame
  for (var frameKey in audioData.byFrame) {
    var audioSegment = audioData.byFrame[frameKey];
    var segmentStart = audioSegment.start_time;
    var segmentEnd = audioSegment.end_time;

    if (timeSeconds >= segmentStart && timeSeconds <= segmentEnd) {
      return audioSegment;
    }
  }

  return null;
}
```

