function applySyncCorrection(comp, offsetSeconds) {
  // Décaler tous les calques audio
  for (var i = 1; i <= comp.numLayers; i++) {
    var layer = comp.layer(i);
    if (layer.hasAudio && !layer.hasVideo) {
      layer.startTime += offsetSeconds;
    }
  }

  // Ajuster expressions temporelles
  for (var i = 1; i <= comp.numLayers; i++) {
    var layer = comp.layer(i);
    if (layer.property('Source Text')) {
      var textProp = layer.property('Source Text');
      if (textProp.expression) {
