La gestion d'erreurs robuste dans ExtendScript inclut des fallbacks multiples et une validation continue pour éviter les crashs AE :

## Patterns de Gestion d'Erreurs

**Structure try-catch général :**
```javascript
function safeExecute(operation, fallback) {
  try {
    return operation();
  } catch (e) {
    $.writeln('[ERROR] ' + operation.name + ': ' + e.message);
    if (fallback) {
      try {
        return fallback(e);
      } catch (fallbackError) {
        $.writeln('[FALLBACK FAILED] ' + fallback.name + ': ' + fallbackError.message);
        return null;
      }
    }
    return null;
  }
}

function loadTrackingDataSafe(videoPath) {
  return safeExecute(
    function() { return loadTrackingData(videoPath); },
    function(error) { return loadFallbackData(videoPath, error); }
  );
}
```

## Fallbacks Hiérarchiques

**Chargement de données avec dégradation :**
```javascript
function loadTrackingDataWithFallback(videoPath) {
  var candidates = [
    { path: videoPath.replace('.mp4', '_ae.json'), priority: 1, type: 'STEP7' },
    { path: videoPath.replace('.mp4', '_tracking.json'), priority: 2, type: 'STEP6' },
    { path: videoPath.replace('.mp4', '.json'), priority: 3, type: 'STEP5' }
  ];

  for (var i = 0; i < candidates.length; i++) {
    var candidate = candidates[i];
    var file = new File(candidate.path);

    if (file.exists) {
      try {
        var data = JSON.parse(file.read());

        // Validation selon le type
        if (validateDataFormat(data, candidate.type)) {
          $.writeln('[SUCCESS] Loaded ' + candidate.type + ' data: ' + candidate.path);
          return {
            data: data,
            source: candidate.type,
            priority: candidate.priority
          };
        } else {
          $.writeln('[VALIDATION FAILED] Invalid format for ' + candidate.type);
        }
      } catch (parseError) {
        $.writeln('[PARSE ERROR] ' + candidate.path + ': ' + parseError.message);
      }
    } else {
      $.writeln('[MISSING] ' + candidate.path + ' not found');
    }
  }

  throw new Error('Aucune donnée de tracking valide trouvée');
}

function validateDataFormat(data, type) {
  switch (type) {
    case 'STEP7':
      return data.metadata && data.dataByFrame;
    case 'STEP6':
      return data.tracking && data.analytics;
    case 'STEP5':
      return data.tracking && Array.isArray(data.tracking);
    default:
      return false;
  }
}
```

## Gestion des Erreurs de Mémoire

**Parsing streaming pour gros fichiers :**
```javascript
function loadLargeTrackingFile(filePath) {
  var file = new File(filePath);
  file.open('r');

  var data = { tracking: [] };
  var buffer = '';
  var lineCount = 0;

  try {
    while (!file.eof) {
      var line = file.readln();
      buffer += line;\lineCount++;

      // Traitement par chunks
      if (buffer.length > 50000 || lineCount % 100 === 0) {
        try {
          processBufferChunk(buffer, data);
          buffer = '';
        } catch (chunkError) {
          $.writeln('[CHUNK ERROR] Line ' + lineCount + ': ' + chunkError.message);
          // Continuer avec le chunk suivant
        }
      }

      // Protection contre les fichiers trop gros
      if (lineCount > 100000) {
        $.writeln('[SIZE LIMIT] File too large, stopping at line ' + lineCount);
        break;
      }
    }

    // Traiter le buffer restant
    if (buffer.length > 0) {
      processBufferChunk(buffer, data);
    }

  } catch (readError) {
    $.writeln('[READ ERROR] ' + readError.message);
  } finally {
    file.close();
  }

  return data;
}

function processBufferChunk(buffer, data) {
  // Parser partiellement le JSON
  var lines = buffer.split('\n');
  for (var i = 0; i < lines.length; i++) {
    if (lines[i].trim()) {
      try {
        var chunk = JSON.parse(lines[i]);
        if (chunk.tracking) {
          data.tracking = data.tracking.concat(chunk.tracking);
        }
      } catch (parseError) {
        // Ignorer les lignes malformées
      }
    }
  }
}
```

## Validation de Données

**Checks de cohérence :**
```javascript
function validateTrackingData(data, source) {
  var issues = [];

  if (!data) {
    issues.push('Données nulles');
    return issues;
  }

  // Validation selon la source
  switch (source) {
    case 'STEP7':
      if (!data.metadata) issues.push('Metadata manquante');
      if (!data.dataByFrame) issues.push('dataByFrame manquant');
      break;

    case 'STEP6':
    case 'STEP5':
      if (!data.tracking) issues.push('Tracking data manquante');
      if (!Array.isArray(data.tracking)) issues.push('Tracking n\'est pas un array');
      break;
  }

  // Validation temporelle
  if (data.metadata && data.metadata.total_frames) {
    var expectedFrames = data.metadata.total_frames;
    var actualFrames = Object.keys(data.dataByFrame || {}).length;

    if (actualFrames < expectedFrames * 0.8) {
      issues.push('Couverture temporelle insuffisante: ' + actualFrames + '/' + expectedFrames);
    }
  }

  // Validation des visages
  if (data.dataByFrame) {
    var faceCount = 0;
    for (var frameKey in data.dataByFrame) {
      faceCount += data.dataByFrame[frameKey].length;
    }

    if (faceCount === 0) {
      issues.push('Aucun visage détecté');
    }
  }

  return issues;
}
```

## Gestion des Ponts Python

**Fallbacks pour system.callSystem() :**
```javascript
function callPythonBridge(command, timeout) {
  timeout = timeout || 30000; // 30 secondes par défaut

  try {
    var startTime = new Date().getTime();
    var result = system.callSystem(command);
    var endTime = new Date().getTime();

    // Vérifier timeout
    if (endTime - startTime > timeout) {
      $.writeln('[TIMEOUT] Python bridge exceeded ' + timeout + 'ms');
      return { success: false, error: 'timeout', timeout: true };
    }

    // Vérifier résultat
    if (result.indexOf('ERROR') !== -1 || result.indexOf('Traceback') !== -1) {
      return { success: false, error: result, python_error: true };
    }

    return { success: true, result: result };

  } catch (systemError) {
    $.writeln('[SYSTEM ERROR] callSystem failed: ' + systemError.message);
    return { success: false, error: systemError.message, system_error: true };
  }
}

function callPythonWithFallback(primaryCommand, fallbackCommand) {
  var result = callPythonBridge(primaryCommand);

  if (!result.success) {
    $.writeln('[FALLBACK] Primary failed, trying fallback...');
    result = callPythonBridge(fallbackCommand);
  }

  if (!result.success) {
    $.writeln('[CRITICAL] Both Python calls failed');
    // Continuer avec logique ExtendScript pure
    return executeExtendScriptFallback();
  }

  return result;
}
```

## Logging et Monitoring

**Système de logs structuré :**
```javascript
function logError(context, error, level) {
  level = level || 'ERROR';
  var timestamp = new Date().toISOString();
  var message = '[' + level + '] [' + timestamp + '] ' + context + ': ' + error.message;

  $.writeln(message);

  // Écrire dans fichier log si possible
  try {
    var logFile = new File(Folder.temp + '/ae_script_errors.log');
    logFile.open('a');
    logFile.writeln(message);
    logFile.close();
  } catch (logError) {
    // Impossible d'écrire le log
  }
}

function createErrorReport(comp, issues) {
  var reportLayer = comp.layers.addText('Error Report');
  var textProp = reportLayer.property('Source Text');

  var report = 'RAPPORT D\'ERREURS\n================\n\n';
  report += 'Timestamp: ' + new Date().toISOString() + '\n';
  report += 'Issues trouvés: ' + issues.length + '\n\n';

  for (var i = 0; i < issues.length; i++) {
    report += (i + 1) + '. ' + issues[i] + '\n';
  }

  var textDoc = textProp.value;
  textDoc.text = report;
  textDoc.fontSize = 24;
  textDoc.fillColor = [1, 0, 0]; // Rouge pour erreurs
  textProp.setValue(textDoc);

  return reportLayer;
}
```

## Recovery Automatique

**Tentatives de réparation :**
```javascript
function attemptRecovery(comp, errorType, context) {
  switch (errorType) {
    case 'memory':
      // Réduire la qualité
      app.preferences.setPrefAsLong('Main Pref Section v2', 'memory', 0);
      return true;

    case 'file_missing':
      // Chercher fichiers alternatifs
      return findAlternativeFiles(context);

    case 'parsing':
      // Essayer parsing partiel
      return attemptPartialParsing(context);

    case 'python_bridge':
      // Reconfiguration PYTHON_EXECUTABLE
      return reconfigurePythonPath();

    default:
      return false;
  }
}
