function createOptimizedKeyframes(positionProp, keyframes, tolerance) {
  if (keyframes.length <= 100) return keyframes; // Pas besoin d'optimiser

  var optimized = [keyframes[0]]; // Garder premier

  for (var i = 1; i < keyframes.length - 1; i++) {
    var prev = optimized[optimized.length - 1];
    var curr = keyframes[i];
    var next = keyframes[i + 1];

    // Calculer courbure (changement de direction)
    var curvature = calculateKeyframeCurvature(prev.position, curr.position, next.position);

    // Garder seulement les keyframes importants
    if (curvature > tolerance || i % 10 === 0) { // Échantillonnage tous les 10 frames
      optimized.push(curr);
    }
  }

  optimized.push(keyframes[keyframes.length - 1]); // Garder dernier

  return optimized;
}

function calculateKeyframeCurvature(p1, p2, p3) {
  // Distance du point milieu à la ligne p1-p3
  var lineDist = pointToLineDistance(p2, p1, p3);
  return lineDist;
}

function pointToLineDistance(point, line1, line2) {
  var A = point[0] - line1[0];
  var B = point[1] - line1[1];
  var C = line2[0] - line1[0];
  var D = line2[1] - line1[1];

  var dot = A * C + B * D;
  var lenSq = C * C + D * D;

  if (lenSq === 0) return Math.sqrt(A * A + B * B);

  var param = dot / lenSq;

  var xx, yy;
  if (param < 0) {
    xx = line1[0];
    yy = line1[1];
  } else if (param > 1) {
    xx = line2[0];
    yy = line2[1];
  } else {
    xx = line1[0] + param * C;
    yy = line1[1] + param * D;
  }

  return Math.sqrt((point[0] - xx) * (point[0] - xx) + (point[1] - yy) * (point[1] - yy));
}
```

## Traitement par Batches

**Division des longues séquences :**
```javascript
function processVideoInBatches(aeJson, batchSize) {
  batchSize = batchSize || 1000; // Frames par batch

  var totalFrames = aeJson.metadata.total_frames;
  var batches = [];

  for (var startFrame = 1; startFrame <= totalFrames; startFrame += batchSize) {
    var endFrame = Math.min(startFrame + batchSize - 1, totalFrames);

    batches.push({
      startFrame: startFrame,
      endFrame: endFrame,
      data: extractBatchData(aeJson, startFrame, endFrame)
    });
  }

  return batches;
}

function extractBatchData(aeJson, startFrame, endFrame) {
  var batchData = {
    metadata: aeJson.metadata,
    dataByFrame: {}
  };

  for (var frame = startFrame; frame <= endFrame; frame++) {
    var frameKey = frame.toString();
    if (aeJson.dataByFrame[frameKey]) {
      batchData.dataByFrame[frameKey] = aeJson.dataByFrame[frameKey];
    }
  }

  return batchData;
}
```

## Optimisation des Expressions

**Expressions légères pour les propriétés :**
```javascript
// Au lieu d'expressions complexes, utiliser des valeurs statiques
function replaceComplexExpressions(layer) {
  var timeProperties = ['position', 'scale', 'rotation', 'opacity'];

  for (var i = 0; i < timeProperties.length; i++) {
    var propName = timeProperties[i];

    if (layer.property(propName) && layer.property(propName).expression) {
      var expression = layer.property(propName).expression;

      // Si expression simple, la remplacer par keyframes
      if (isSimpleExpression(expression)) {
        bakeExpressionToKeyframes(layer.property(propName));
      }
    }
  }
}

function bakeExpressionToKeyframes(prop) {
  var comp = prop.propertyGroup(prop.propertyDepth).containingComp;
  var frameRate = comp.frameRate;
  var duration = comp.duration;

  // Échantillonnage de l'expression
  for (var time = 0; time <= duration; time += 1/frameRate) {
    try {
      var value = prop.valueAtTime(time, false);
      prop.setValueAtTime(time, value);
    } catch (e) {
      // Ignorer les erreurs d'évaluation
    }
  }

  // Supprimer l'expression
  prop.expression = '';
}
