## Gestion des Calques

**Désactivation intelligente :**
```javascript
function optimizeLayerVisibility(comp) {
  var visibleLayers = 0;

  for (var i = 1; i <= comp.numLayers; i++) {
    var layer = comp.layer(i);

    // Désactiver les calques hors écran
    if (isLayerOffScreen(layer, comp)) {
      layer.enabled = false;
      layer.shy = true;
    }

    // Ajuster qualité selon importance
    if (layer.name.indexOf('Background') !== -1) {
      layer.quality = LayerQuality.DRAFT;
    } else if (visibleLayers < 10) {
      layer.quality = LayerQuality.BEST;
      visibleLayers++;
    } else {
      layer.quality = LayerQuality.GOOD;
    }
  }
}

function isLayerOffScreen(layer, comp) {
  if (!layer.hasVideo) return false;

  var layerRect = layer.sourceRectAtTime(0, false);
  var compRect = {
    left: 0,
    top: 0,
    right: comp.width,
    bottom: comp.height
  };

  return (layerRect.left > compRect.right || 
          layerRect.right < compRect.left || 
          layerRect.top > compRect.bottom || 
          layerRect.bottom < compRect.top);
}
```

## Cache et Pré-calculs

**Pré-calcul des valeurs complexes :**
```javascript
function precomputeComplexValues(aeJson) {
  var cache = {};

  // Pré-calcul des distances inter-landmarks
  for (var frameKey in aeJson.dataByFrame) {
    var frameData = aeJson.dataByFrame[frameKey];

    for (var i = 0; i < frameData.length; i++) {
      var face = frameData[i];

      if (face.landmarks && face.landmarks.length >= 68) {
        var distances = {
          eyeDistance: calculateDistance(face.landmarks[36], face.landmarks[45]),
          mouthWidth: calculateDistance(face.landmarks[48], face.landmarks[54]),
          faceHeight: calculateDistance(face.landmarks[27], face.landmarks[8])
        };

        cache[frameKey + '_' + face.id] = distances;
      }
    }
  }

  return cache;
}

function calculateDistance(point1, point2) {
  var dx = point2.x - point1.x;
  var dy = point2.y - point1.y;
  return Math.sqrt(dx * dx + dy * dy);
}
```

