if (faceData && faceData.landmarks) {
  var targetPos = faceData.landmarks[30];
  var currentPos = value;

  var distance = length(targetPos - currentPos);

  if (distance > threshold) {
    targetPos;
  } else {
    currentPos; // Garder la position actuelle
  }
