## Rendu Progressif

**Rendu par segments pour les longs métrages :**
```javascript
function renderInSegments(comp, exportPath, segmentDuration) {
  segmentDuration = segmentDuration || 300; // 5 minutes par défaut

  var totalDuration = comp.duration;
  var segments = [];

  for (var startTime = 0; startTime < totalDuration; startTime += segmentDuration) {
    var endTime = Math.min(startTime + segmentDuration, totalDuration);

    segments.push({
      start: startTime,
      end: endTime,
      duration: endTime - startTime
    });
  }

  // Rendre chaque segment
  for (var i = 0; i < segments.length; i++) {
    var segment = segments[i];
    var segmentFile = exportPath.replace('.mp4', '_part' + (i + 1) + '.mp4');

    renderSegment(comp, segment.start, segment.end, segmentFile);

    $.writeln('[RENDER] Segment ' + (i + 1) + '/' + segments.length + ' completed');
  }

  // Concaténer les segments si nécessaire
  if (segments.length > 1) {
    concatenateSegments(segments, exportPath);
  }
}

function renderSegment(comp, startTime, endTime, outputPath) {
  var renderQueue = app.project.renderQueue;
  var renderItem = renderQueue.items.add(comp);

  // Configurer la plage temporelle
  var timeSpanStart = startTime / comp.duration;
  var timeSpanEnd = endTime / comp.duration;

  var renderSettings = renderItem.getSettings(GetSettingsFormat.STRING_SET);
  renderSettings["Time_Span_Start"] = timeSpanStart;
  renderSettings["Time_Span_End"] = timeSpanEnd;
  renderSettings["Time_Span_Duration"] = timeSpanEnd - timeSpanStart;

  renderItem.setSettings(renderSettings);

  // Configurer sortie
  var outputModule = renderItem.outputModule(1);
  outputModule.file = new File(outputPath);

  // Lancer le rendu
  renderQueue.render();

  // Attendre la fin
  while (renderQueue.rendering) {
    $.sleep(1000);
  }
}
```

