  var metadataFile = new File(exportPaths.data);
  if (!metadataFile.exists) {
    issues.push('Fichier métadonnées manquant');
  } else {
    try {
      metadataFile.open('r');
      var metadata = JSON.parse(metadataFile.read());
      metadataFile.close();

      if (!metadata.project_info || !metadata.tracking_source) {
        issues.push('Métadonnées incomplètes');
      }
    } catch (e) {
      issues.push('Erreur lecture métadonnées: ' + e.message);
    }
  }

  return issues;
}

function getVideoDuration(videoPath) {
  // Utiliser ffprobe ou similaire via system.callSystem
  var cmd = 'ffprobe -v quiet -print_format json -show_format "' + videoPath + '"';
  var result = system.callSystem(cmd);

  try {
    var probeData = JSON.parse(result);
    return parseFloat(probeData.format.duration);
  } catch (e) {
    return 0;
  }
}
```

