Le debugging des scripts ExtendScript nécessite un système de logging robuste et des techniques de diagnostic adaptées à l'environnement AE :

## Système de Logging Structuré

**Logger principal avec niveaux :**
```javascript
function Logger(logLevel) {
  this.level = logLevel || 'INFO';
  this.levels = { 'DEBUG': 0, 'INFO': 1, 'WARN': 2, 'ERROR': 3 };
  this.logs = [];

  this.log = function(level, message, context) {
    if (this.levels[level] >= this.levels[this.level]) {
      var timestamp = new Date().toISOString();
      var formattedMessage = '[' + level + '] [' + timestamp + '] ' + 
                           (context ? '[' + context + '] ' : '') + message;

      // Console AE
      $.writeln(formattedMessage);

      // Stockage mémoire
      this.logs.push({
        timestamp: timestamp,
        level: level,
        context: context,
        message: message
      });

      // Fichier si critique
      if (level === 'ERROR' || level === 'WARN') {
        this.writeToFile(formattedMessage);
      }
    }
  };

  this.debug = function(message, context) { this.log('DEBUG', message, context); };
  this.info = function(message, context) { this.log('INFO', message, context); };
  this.warn = function(message, context) { this.log('WARN', message, context); };
  this.error = function(message, context) { this.log('ERROR', message, context); };

  this.writeToFile = function(message) {
    try {
      var logFile = new File(Folder.temp + '/ae_debug.log');
      logFile.open('a');
      logFile.writeln(message);
      logFile.close();
    } catch (e) {
      // Silent fail pour éviter récursion
    }
  };

  this.exportLogs = function() {
    var logFile = new File(Folder.desktop + '/ae_logs_' + new Date().getTime() + '.txt');
    logFile.open('w');

    for (var i = 0; i < this.logs.length; i++) {
      logFile.writeln(JSON.stringify(this.logs[i]));
    }

    logFile.close();
    return logFile.path;
  };
}

var logger = new Logger('DEBUG');
```

## Debugging des Données de Tracking

**Validation et diagnostic des données :**
```javascript
function debugTrackingData(data, source) {
  logger.info('=== DEBUG TRACKING DATA ===', 'debug');
  logger.info('Source: ' + source, 'debug');

  if (!data) {
    logger.error('Data is null or undefined', 'debug');
    return false;
  }

  // Vérifications structure
  if (data.metadata) {
    logger.debug('Metadata: fps=' + data.metadata.fps + ', frames=' + data.metadata.total_frames, 'debug');
  } else {
    logger.warn('No metadata found', 'debug');
  }

  if (data.dataByFrame) {
    var frameCount = Object.keys(data.dataByFrame).length;
    logger.debug('Frames with data: ' + frameCount, 'debug');

    // Analyse échantillon
    var sampleFrame = Object.keys(data.dataByFrame)[0];
    var sampleData = data.dataByFrame[sampleFrame];

    if (sampleData && sampleData.length > 0) {
      var face = sampleData[0];
      logger.debug('Sample face data: id=' + face.id + ', confidence=' + face.confidence, 'debug');

      if (face.landmarks) {
        logger.debug('Landmarks count: ' + face.landmarks.length, 'debug');
      }

      if (face.blendshapes) {
        var bsKeys = Object.keys(face.blendshapes);
        logger.debug('Blendshapes: ' + bsKeys.slice(0, 3).join(', ') + '...', 'debug');
      }
    }
  } else {
    logger.error('No dataByFrame found', 'debug');
  }

  // Vérifications cohérence
  return validateDataConsistency(data);
}

function validateDataConsistency(data) {
  var issues = [];

  if (data.metadata && data.dataByFrame) {
    var expectedFrames = data.metadata.total_frames;
    var actualFrames = Object.keys(data.dataByFrame).length;
    var coverage = (actualFrames / expectedFrames) * 100;

    logger.debug('Coverage: ' + coverage.toFixed(1) + '% (' + actualFrames + '/' + expectedFrames + ')', 'debug');

    if (coverage < 50) {
      issues.push('Low coverage: ' + coverage.toFixed(1) + '%');
    }
  }

  // Vérification timestamps
  var frameKeys = Object.keys(data.dataByFrame || {});
  if (frameKeys.length > 0) {
    var firstFrame = parseInt(frameKeys[0]);
    var lastFrame = parseInt(frameKeys[frameKeys.length - 1]);

    if (firstFrame !== 1) {
      issues.push('Does not start at frame 1: ' + firstFrame);
    }

    logger.debug('Frame range: ' + firstFrame + ' to ' + lastFrame, 'debug');
  }

  if (issues.length > 0) {
    logger.warn('Consistency issues: ' + issues.join(', '), 'debug');
    return false;
  }

  logger.info('Data validation passed', 'debug');
  return true;
}
```

## Debugging des Expressions

**Monitoring des expressions AE :**
```javascript
function debugExpression(layer, propName, time) {
  try {
    var prop = layer.property(propName);
    if (prop && prop.expression) {
      var expression = prop.expression;

      // Tester l'évaluation
      var testValue = prop.valueAtTime(time, false);
      logger.debug('Expression result at ' + time.toFixed(2) + 's: ' + JSON.stringify(testValue), 'expression');

      // Analyser les erreurs potentielles
      if (typeof testValue === 'undefined' || testValue === null) {
        logger.warn('Expression returned null/undefined', 'expression');

        // Vérifier les dépendances
        checkExpressionDependencies(expression, layer, time);
      }

    } else {
      logger.debug('No expression on ' + propName, 'expression');
    }
  } catch (e) {
    logger.error('Expression error: ' + e.message, 'expression');
    logger.debug('Expression code: ' + expression, 'expression');
  }
}

function checkExpressionDependencies(expression, layer, time) {
  // Vérifier présence de fonctions globales
  if (expression.indexOf('getTrackingDataAtTime') !== -1) {
    logger.debug('Uses getTrackingDataAtTime - checking if defined', 'expression');

    if (typeof getTrackingDataAtTime === 'undefined') {
      logger.error('getTrackingDataAtTime not defined globally', 'expression');
    }
  }

  if (expression.indexOf('thisComp') !== -1) {
    logger.debug('Uses thisComp - checking context', 'expression');

    if (typeof thisComp === 'undefined') {
      logger.warn('thisComp not available in this context', 'expression');
    }
  }
}
```

## Debugging des Ponts Python

**Diagnostic appels système :**
```javascript
function debugPythonBridge(command, expectedOutput) {
  logger.info('=== DEBUG PYTHON BRIDGE ===', 'python');
  logger.debug('Command: ' + command, 'python');

  var startTime = new Date().getTime();

  try {
    var result = system.callSystem(command);
    var endTime = new Date().getTime();

    logger.debug('Execution time: ' + (endTime - startTime) + 'ms', 'python');
    logger.debug('Raw output length: ' + result.length + ' chars', 'python');

    // Analyser le résultat
    if (result.indexOf('Traceback') !== -1) {
      logger.error('Python error detected', 'python');
      logger.debug('Python traceback: ' + result, 'python');
      return { success: false, error: 'python_error', details: result };
    }

    if (result.indexOf('ERROR') !== -1) {
      logger.warn('Error keyword in output', 'python');
    }

    // Validation format attendu
    if (expectedOutput === 'json') {
      try {
        JSON.parse(result);
        logger.debug('Output is valid JSON', 'python');
      } catch (e) {
        logger.warn('Output is not valid JSON', 'python');
      }
    }

    logger.debug('Bridge call successful', 'python');
    return { success: true, result: result };

  } catch (systemError) {
    logger.error('System call failed: ' + systemError.message, 'python');
    return { success: false, error: 'system_error', details: systemError.message };
  }
}
```

## Profiling et Performance

**Mesure des performances :**
```javascript
function createProfiler() {
  var profiles = {};

  return {
    start: function(label) {
      profiles[label] = { start: new Date().getTime() };
      logger.debug('Started profiling: ' + label, 'profile');
    },

    end: function(label) {
      if (profiles[label]) {
        var duration = new Date().getTime() - profiles[label].start;
        logger.debug('Profile ' + label + ': ' + duration + 'ms', 'profile');

        if (duration > 1000) {
          logger.warn('Slow operation: ' + label + ' took ' + duration + 'ms', 'profile');
        }

        delete profiles[label];
      }
    },

    profileFunction: function(label, fn) {
      this.start(label);
      try {
        var result = fn();
        this.end(label);
        return result;
      } catch (e) {
        this.end(label);
        throw e;
      }
    }
  };
}

var profiler = createProfiler();

// Usage
profiler.profileFunction('loadTrackingData', function() {
  return loadTrackingData(videoPath);
});
