function runDebugChecklist(comp) {
  var checklist = [
    { name: 'Data Loading', test: function() { return testDataLoading(comp); } },
    { name: 'Expression Evaluation', test: function() { return testExpressions(comp); } },
    { name: 'Python Bridge', test: function() { return testPythonBridge(); } },
