// static/utils/ErrorHandler.js
export class ErrorHandler {
  static handleApiError(error, context) {
    console.error(`Erreur API ${context}:`, error);

    if (error.response) {
      // Erreur HTTP
      const status = error.response.status;
      const message = error.response.data?.error || 'Erreur inconnue';

      switch (status) {
        case 400:
          return this.showValidationError(message);
        case 500:
          return this.showSystemError(message);
        default:
          return this.showGenericError(message);
      }
    } else if (error.request) {
      // Erreur réseau
      return this.showNetworkError();
    } else {
      // Erreur autre
      return this.showGenericError(error.message);
    }
  }
}
