# services/workflow_service.py
def run_step_async(self, step_key: str) -> Dict[str, str]:
    """Lance une étape en arrière-plan de façon thread-safe."""
    ws = get_workflow_state()

    # Vérifications atomiques
    with ws._state_lock:
        if ws.is_sequence_running():
            return {'status': 'error', 'message': 'Séquence en cours'}

        if ws.is_step_running(step_key):
            return {'status': 'error', 'message': 'Étape déjà en cours'}

    # Lancement thread
    thread = threading.Thread(
        target=self._execute_step_thread,
        args=(step_key,),
        daemon=True
    )
    thread.start()

    return {'status': 'initiated'}
