# tests/integration/test_concurrency.py
import threading
import time

def test_concurrent_step_updates():
    """Test mises à jour concurrentes."""
    ws = get_workflow_state()
    results = []

    def worker(thread_id):
        for i in range(10):
            ws.update_step_status('STEP1', f'thread_{thread_id}_{i}')
            time.sleep(0.01)  # Simuler travail
        results.append(f'thread_{thread_id}_done')

    # Lancer 5 threads
    threads = []
    for i in range(5):
        t = threading.Thread(target=worker, args=(i,))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    assert len(results) == 5
    # Vérifier pas de corruption de state
